"""C13 - stale or missing cached values (warning).

Detection:
* no formula has a cached value (the file was generated by a script and never
  opened in a spreadsheet application): values shown are unreliable, and checks
  that read values (C04, C10) cannot see anything;
* manual calculation mode: cached values may be stale;
* some formulas lack a cached value while others have one (info).

Policy: driver analysis never uses cached values; it always recalculates with
the evaluator, so it is unaffected by this issue.
"""

from __future__ import annotations

from collections.abc import Iterable

from sheetguard.checks.base import WORKBOOK_LABEL, Check, CheckContext, make_issue, workbook_key
from sheetguard.core.model import ValueType
from sheetguard.report.schema import Confidence, Issue, Severity


class StaleCachedValues(Check):
    id = "C13"
    title = "Stale or missing cached values"
    default_severity = Severity.WARNING

    def run(self, ctx: CheckContext) -> Iterable[Issue]:
        wb = ctx.wb
        anchor = workbook_key(ctx)
        total = wb.formula_count
        if total and not wb.has_cached_values:
            yield make_issue(
                self.id,
                Severity.WARNING,
                anchor,
                f"None of the {total} formulas has a cached value: the file was probably "
                f"written by a script and never calculated. Values shown are not reliable.",
                confidence=Confidence.HIGH,
                affected_count=total,
                cell_label=WORKBOOK_LABEL,
                discriminator="no-cache",
            )
        elif total:
            missing = sum(1 for _, c in wb.iter_formula_cells() if c.vtype is ValueType.EMPTY)
            if missing:
                yield make_issue(
                    self.id,
                    Severity.INFO,
                    anchor,
                    f"{missing} of {total} formulas have no cached value.",
                    confidence=Confidence.MEDIUM,
                    affected_count=missing,
                    cell_label=WORKBOOK_LABEL,
                    discriminator="partial-cache",
                )
        if wb.calc_mode.lower() == "manual":
            yield make_issue(
                self.id,
                Severity.WARNING,
                anchor,
                "Calculation mode is manual: cached values may be stale.",
                confidence=Confidence.HIGH,
                cell_label=WORKBOOK_LABEL,
                discriminator="manual",
            )
